-- vlsideepdive labs: daily challenge and streaks, public profiles, lab pass rates, study plans and certificates.
-- Run once in the Supabase SQL editor after schema.sql, counters.sql and badges.sql, then run plans.sql
-- (generated by the build). Safe to run again.

-- Today in India (the daily challenge changes at midnight IST).
create or replace function public.ist_today() returns date language sql stable as $$ select (now() at time zone 'Asia/Kolkata')::date $$;

-- 1. Public profile handles: labs.vlsideepdive.com/u/?h=<handle>
alter table public.profiles add column if not exists handle text;
do $$ begin
  alter table public.profiles add constraint profiles_handle_format check (handle ~ '^[a-z0-9][a-z0-9-]{1,30}[a-z0-9]$');
exception when duplicate_object then null; end $$;
create unique index if not exists profiles_handle_key on public.profiles (handle);

-- 2. Lab pass rates: how many browsers tried each lab and how many solved it (anonymous, like the counters).
create table if not exists public.lab_stats (lab_id text primary key check (lab_id ~ '^[A-Za-z0-9_.-]{1,48}$'), tried int not null default 0, solved int not null default 0);
alter table public.lab_stats enable row level security;
drop policy if exists "lab stats readable" on public.lab_stats;
create policy "lab stats readable" on public.lab_stats for select using (true);
grant select on public.lab_stats to anon, authenticated;

drop function if exists public.bump_counters(jsonb, uuid);
create or replace function public.bump_counters(c jsonb, batch uuid, l jsonb default '{}'::jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare k text; v int; t int; s int; fresh int; nl int := 0;
begin
  insert into public.counter_batches (id) values (batch) on conflict (id) do nothing;
  get diagnostics fresh = row_count;
  if fresh = 0 then return; end if;   -- already counted
  for k, v in select key, least(greatest(round((value #>> '{}')::numeric)::int, 0), 50) from jsonb_each(c) where jsonb_typeof(value) = 'number' loop
    update public.counters set n = counters.n + v where name = k;
  end loop;
  for k in select key from jsonb_each(coalesce(l, '{}'::jsonb)) where key ~ '^[A-Za-z0-9_.-]{1,48}$' loop
    nl := nl + 1; exit when nl > 60;
    t := case when (l -> k ->> 't') = '1' then 1 else 0 end;
    s := case when (l -> k ->> 's') = '1' then 1 else 0 end;
    insert into public.lab_stats (lab_id, tried, solved) values (k, t, s)
      on conflict (lab_id) do update set tried = lab_stats.tried + t, solved = lab_stats.solved + s;
  end loop;
  if random() < 0.01 then delete from public.counter_batches where at < now() - interval '30 days'; end if;
end $$;
revoke all on function public.bump_counters(jsonb, uuid, jsonb) from public;
grant execute on function public.bump_counters(jsonb, uuid, jsonb) to anon, authenticated;

-- 3. Daily challenge: the days each person solved it.
create table if not exists public.daily_done (
  user_id uuid not null references auth.users (id) on delete cascade,
  day date not null,
  lab_id text not null check (lab_id ~ '^[A-Za-z0-9_.-]{1,48}$'),
  primary key (user_id, day),
  check (day between date '2026-11-01' and date '2100-01-01')
);
alter table public.daily_done enable row level security;
drop policy if exists "own daily read" on public.daily_done;
drop policy if exists "own daily insert" on public.daily_done;
create policy "own daily read" on public.daily_done for select using (auth.uid() = user_id);
create policy "own daily insert" on public.daily_done for insert
  with check (auth.uid() = user_id and day between public.ist_today() - 7 and public.ist_today() + 1);
grant select, insert on public.daily_done to authenticated;

-- Streaks: the current run (still alive if it reaches today or yesterday) and the best run.
create or replace view public.streaks as
  with g as (select user_id, day, day - (row_number() over (partition by user_id order by day))::int as grp from public.daily_done),
       runs as (select user_id, max(day) as last, count(*)::int as len from g group by user_id, grp)
  select user_id, coalesce(max(len) filter (where last >= public.ist_today() - 1), 0)::int as current, max(len)::int as best, sum(len)::int as days
  from runs group by user_id;

-- Monthly daily-challenge badges ("daily-2026-11") next to the video badges.
alter table public.badges drop constraint if exists badges_badge_id_check;
alter table public.badges add constraint badges_badge_id_check check (badge_id ~ '^(yt-[A-Za-z0-9_-]{11}|daily-[0-9]{4}-[0-9]{2})$');

-- 4. Leaderboards: as before, plus handle (for profile links) and current streak.
create or replace view public.leaderboard as
  select g.topic, g.user_id, p.display_name, g.points, g.labs_passed, g.quizzes, g.reached_at,
         rank() over (partition by g.topic order by g.points desc, coalesce(b.n, 0) desc, g.reached_at asc) as rank,
         coalesce(b.n, 0)::int as badges, p.handle, coalesce(s.current, 0)::int as streak
  from (
    select topic, user_id,
           sum(case when passed then 10 else 0 end + quiz_score)::int as points,
           count(*) filter (where passed)::int as labs_passed,
           count(*) filter (where quiz_total > 0)::int as quizzes,
           max(updated_at) as reached_at
    from public.progress group by topic, user_id
  ) g join public.profiles p on p.id = g.user_id
  left join (select user_id, count(*) as n from public.badges group by user_id) b on b.user_id = g.user_id
  left join public.streaks s on s.user_id = g.user_id
  where g.points > 0;

create or replace view public.leaderboard_all as
  select 'all'::text as topic, u.user_id, p.display_name,
         coalesce(g.points, 0)::int as points, coalesce(g.labs_passed, 0)::int as labs_passed, coalesce(g.quizzes, 0)::int as quizzes,
         coalesce(greatest(g.reached_at, b.last), g.reached_at, b.last) as reached_at,
         rank() over (order by coalesce(g.points, 0) desc, coalesce(b.n, 0) desc, coalesce(greatest(g.reached_at, b.last), g.reached_at, b.last) asc) as rank,
         coalesce(b.n, 0)::int as badges, p.handle, coalesce(s.current, 0)::int as streak
  from (select user_id from public.progress union select user_id from public.badges union select user_id from public.daily_done) u
  join public.profiles p on p.id = u.user_id
  left join (
    select user_id,
           sum(case when passed then 10 else 0 end + quiz_score)::int as points,
           count(*) filter (where passed)::int as labs_passed,
           count(*) filter (where quiz_total > 0)::int as quizzes,
           max(updated_at) as reached_at
    from public.progress group by user_id
  ) g on g.user_id = u.user_id
  left join (select user_id, count(*) as n, max(earned_at) as last from public.badges group by user_id) b on b.user_id = u.user_id
  left join public.streaks s on s.user_id = u.user_id
  where coalesce(g.points, 0) > 0 or coalesce(b.n, 0) > 0 or coalesce(s.days, 0) > 0;
grant select on public.leaderboard, public.leaderboard_all to anon, authenticated;

-- 5. Study plans and certificates. plans.sql (generated) fills public.plans.
create table if not exists public.plans (plan_id text primary key, title text not null, labs text[] not null);
alter table public.plans enable row level security;   -- read only by the certificate function

create table if not exists public.certificates (
  id text primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  plan_id text not null references public.plans (plan_id),
  name text not null check (char_length(name) between 2 and 60),
  issued_at timestamptz not null default now(),
  unique (user_id, plan_id)
);
alter table public.certificates enable row level security;
drop policy if exists "own certificates read" on public.certificates;
create policy "own certificates read" on public.certificates for select using (auth.uid() = user_id);
grant select on public.certificates to authenticated;

-- Issue (or re-issue with a new name) a certificate once every lab of the plan is done:
-- the lab passed, or its quiz checked with at least half the answers right.
create or replace function public.issue_certificate(p_plan text, p_name text) returns text
language plpgsql security definer set search_path = public as $$
declare uid uuid := auth.uid(); labs text[]; missing int; cid text;
begin
  if uid is null then raise exception 'sign in first'; end if;
  if char_length(trim(p_name)) < 2 then raise exception 'name too short'; end if;
  select pl.labs into labs from public.plans pl where pl.plan_id = p_plan;
  if labs is null then raise exception 'unknown plan'; end if;
  select count(*) into missing from unnest(labs) as x(lab)
    where not exists (select 1 from public.progress pr where pr.user_id = uid and pr.lab_id = x.lab
                      and (pr.passed or (pr.quiz_total > 0 and pr.quiz_score * 2 >= pr.quiz_total)));
  if missing > 0 then raise exception 'plan not complete: % labs left', missing; end if;
  insert into public.certificates (id, user_id, plan_id, name)
    values ('VDD-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8)), uid, p_plan, left(trim(p_name), 60))
    on conflict (user_id, plan_id) do update set name = excluded.name
    returning id into cid;
  return cid;
end $$;
revoke all on function public.issue_certificate(text, text) from public;
grant execute on function public.issue_certificate(text, text) to authenticated;

-- 6. Public views for profile pages and certificate checks (only what a profile page shows).
create or replace view public.profile_public as
  select p.handle, p.display_name, p.created_at as joined,
         coalesce(a.points, 0) as points, coalesce(a.labs_passed, 0) as labs_passed, coalesce(a.quizzes, 0) as quizzes,
         coalesce(a.badges, 0) as badges, a.rank, coalesce(s.current, 0) as streak, coalesce(s.best, 0) as best_streak,
         coalesce(s.days, 0) as daily_days
  from public.profiles p
  left join public.leaderboard_all a on a.user_id = p.id
  left join public.streaks s on s.user_id = p.id
  where p.handle is not null;

create or replace view public.profile_topics as
  select p.handle, l.topic, l.points, l.labs_passed, l.quizzes, l.rank
  from public.leaderboard l join public.profiles p on p.id = l.user_id where p.handle is not null;

create or replace view public.profile_activity as
  select p.handle, a.day, sum(a.n)::int as n
  from (
    select user_id, (first_at at time zone 'Asia/Kolkata')::date as day, count(*) as n from public.progress group by 1, 2
    union all select user_id, day, 1 from public.daily_done
    union all select user_id, (earned_at at time zone 'Asia/Kolkata')::date, 1 from public.badges
  ) a join public.profiles p on p.id = a.user_id
  where p.handle is not null and a.day > public.ist_today() - 371
  group by p.handle, a.day;

create or replace view public.profile_badges as
  select p.handle, b.badge_id, b.title, b.earned_at
  from public.badges b join public.profiles p on p.id = b.user_id where p.handle is not null;

create or replace view public.cert_public as
  select c.id, c.name, c.plan_id, pl.title, array_length(pl.labs, 1) as labs, c.issued_at, p.handle
  from public.certificates c join public.plans pl on pl.plan_id = c.plan_id
  left join public.profiles p on p.id = c.user_id;

grant select on public.profile_public, public.profile_topics, public.profile_activity, public.profile_badges, public.cert_public to anon, authenticated;
